WITH calendar AS (SELECT d::DATE AS mon FROM generate_series(DATE '2024-01-01',DATE '2024-12-01',INTERVAL '1 month') t(d)),paid AS (SELECT o.order_id,date_trunc('month',o.ordered_at AT TIME ZONE 'UTC')::DATE AS mon FROM orders o WHERE o.status = 'paid' AND o.ordered_at >= TIMESTAMPTZ '2024-01-01 00:00:00+00' AND o.ordered_at < TIMESTAMPTZ '2025-01-01 00:00:00+00') SELECT c.mon,count(p.order_id) AS paid_order_count FROM calendar c LEFT JOIN paid p USING(mon) GROUP BY c.mon ORDER BY c.mon;
